G("masks", "IPv4 subnet masks", "d1", "Mask octet values, prefix-to-mask conversion, hosts and block sizes.",
  ["Pattern", "Chunking", "Table", "Active recall"],
  [txt("Pattern: add the next bit value", "Start at 128 and add the next place value each time: 128, +64 = 192, +32 = 224, +16 = 240, +8 = 248, +4 = 252, +2 = 254, +1 = 255. These nine values (with 0) are the ONLY valid mask octets."),
   tab("Prefix within an octet", ["Bits in octet", "1", "2", "3", "4", "5", "6", "7", "8"],
       [["Mask value", "128", "192", "224", "240", "248", "252", "254", "255"], ["Block size", "128", "64", "32", "16", "8", "4", "2", "1"]],
       "Block size = 256 − mask value. It is also the value of the last network bit."),
   tab("Last-octet prefixes (memorize)", ["Prefix", "Mask", "Block", "Usable hosts"],
       [["/24", "255.255.255.0", "256", "254"], ["/25", ".128", "128", "126"], ["/26", ".192", "64", "62"], ["/27", ".224", "32", "30"],
        ["/28", ".240", "16", "14"], ["/29", ".248", "8", "6"], ["/30", ".252", "4", "2"], ["/31", ".254", "2", "2 (P2P, RFC 3021)"], ["/32", ".255", "1", "1 (host route)"]]),
   chunks("Chunk prefixes by octet", [("Octet 2", ["/9 – /16"]), ("Octet 3", ["/17 – /24"]), ("Octet 4", ["/25 – /32"])],
          "Find the octet first, then the position within it: /21 = 3rd octet, 5th bit → 248, block 8."),
   trick("Hosts trick", "Usable hosts are always 2^h − 2 except /31 and /32. Powers of two to know cold: 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096."),
   trick("Trap", "A mask like 255.255.255.200 is invalid — 200 isn't in the list.", "warn")],
  [("Mask for /27?", "255.255.255.224"), ("Mask for /20?", "255.255.240.0"), ("Block size for /29?", "8"), ("Usable hosts in /26?", "62"),
   ("Prefix for 255.255.252.0?", "/22"), ("Mask for /12?", "255.240.0.0")],
  [("255.255.255.248 is which prefix?", ["/28", "/29", "/30", "/27"], 1, "248 = 5 bits in the last octet → 24 + 5 = /29."),
   ("Which is NOT a valid mask octet?", ["252", "248", "236", "128"], 2, "236 is not one of 0/128/192/224/240/248/252/254/255.")])

